('short-form-video','ai-creator','Short-Form Video Studio','Scripts, hooks, editing and repurposing for TikTok, Reels and Shorts.','Creator','Intermediate',105,'creator',5),
('build-your-first-ai-project','ai-tools','Build Your First AI Project','Take one idea from blank page to something you can show people.','Building','Beginner',120,'core',6),
('career-readiness','ai-career','Career Readiness in the AI Era','CV, portfolio, interviews and the skills that now carry a premium.','Career','Beginner',110,'career',7),
('data-literacy','ai-career','Data Literacy for Everyone','Read, question and present data without needing to be an analyst.','Career','Beginner',90,'career',8),
('ai-for-business','ai-entrepreneur','AI for Small Business','Find an offer, reach customers and run operations with a very small team.','Business','Intermediate',110,'creator',9),
('automate-your-workflow','digital-productivity','Automate Your Workflow','Map your week, find the repeat work and hand it to a machine.','Productivity','Beginner',80,'core',10);
